//! Tests of the RTL-SDR protocol layer.
//!
//! * Differential: `tests/golden/scenarios.txt` lists command scripts; `tests/golden/<name>.log` is the transfer log the ORIGINAL librtlsdr (RTL-SDR Blog
//!   fork 1.3.6) produced for it over a fake libusb (`tests/ref/ref_harness.c`, regenerated by `tests/ref/gen_golden.sh`). Each script is replayed here
//!   against the Rust driver: every transfer it makes must equal the next logged one (type, request, value, index, length, timeout, outgoing bytes), the
//!   logged answer is fed back, and every API return value must equal the logged one. 0 mismatches required.
//! * Malformed answers: a fake dongle that errors, answers short or flips bytes; seeded fuzzing of the whole session.

extern crate std;

use crate::fake::{FakeChip, FakeRtl};
use crate::fuzz;
use crate::rtl::{RtlSdr, Tuner};
use crate::transfer::{UsbString, UsbTransfer};
use std::fmt::Write as _;
use std::string::{String, ToString};
use std::vec::Vec;

fn hex(d: &[u8]) -> String {
    let mut s = String::new();
    for b in d {
        write!(s, "{b:02x}").unwrap();
    }
    s
}

fn unhex(s: &str) -> Vec<u8> {
    (0..s.len() / 2).map(|i| u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap()).collect()
}

/// Replays a golden log: checks each transfer against the next `T` line and answers with the logged result.
struct Replay {
    lines: Vec<String>,
    pos: usize,
    mismatches: Vec<String>,
}

impl Replay {
    fn new(log: &str) -> Self {
        Replay { lines: log.lines().map(|l| l.to_string()).collect(), pos: 0, mismatches: Vec::new() }
    }

    fn next_line(&mut self, what: &str) -> Option<String> {
        // the C harness prints R lines between transfers; transfers never skip them
        match self.lines.get(self.pos) {
            Some(l) if l.starts_with("T ") => {
                self.pos += 1;
                Some(l.clone())
            }
            other => {
                self.mismatches.push(std::format!("line {}: wanted a transfer {what}, log has {other:?}", self.pos));
                None
            }
        }
    }

    fn expect_prefix(&mut self, line: &str, prefix: &str) -> bool {
        if line.starts_with(prefix) {
            true
        } else {
            self.mismatches.push(std::format!("line {}: Rust did `{prefix}`, original logged `{line}`", self.pos - 1));
            false
        }
    }

    /// Checks an `R name value` line.
    fn check_r(&mut self, name: &str, value: i64) {
        let want = std::format!("R {name} {value}");
        match self.lines.get(self.pos) {
            Some(l) if *l == want => self.pos += 1,
            other => {
                self.mismatches.push(std::format!("line {}: wanted `{want}`, log has {other:?}", self.pos));
                self.pos += 1;
            }
        }
    }
}

impl UsbTransfer for Replay {
    fn control_in(&mut self, rt: u8, req: u8, value: u16, index: u16, buf: &mut [u8], timeout_ms: u32) -> i32 {
        let Some(line) = self.next_line("IN") else { return -1 };
        let prefix = std::format!("T I {rt:02x} {req:02x} {value:04x} {index:04x} {} {timeout_ms} -> ", buf.len());
        if !self.expect_prefix(&line, &prefix) {
            return -1;
        }
        let rest = &line[prefix.len()..];
        let mut it = rest.split(' ');
        let ret: i32 = it.next().unwrap().parse().unwrap();
        if let Some(h) = it.next() {
            let d = unhex(h);
            buf[..d.len()].copy_from_slice(&d);
        }
        ret
    }

    fn control_out(&mut self, rt: u8, req: u8, value: u16, index: u16, data: &[u8], timeout_ms: u32) -> i32 {
        let Some(line) = self.next_line("OUT") else { return -1 };
        let prefix = std::format!("T O {rt:02x} {req:02x} {value:04x} {index:04x} {} {timeout_ms} {} -> ", data.len(), hex(data));
        // an empty payload is logged as two spaces' worth: "len timeout  -> " (the C prints the hex of zero bytes)
        let prefix = if data.is_empty() { prefix.replace("  ->", " ->") } else { prefix };
        let line = line.replace("  ->", " ->");
        if !self.expect_prefix(&line, &prefix) {
            return -1;
        }
        line[prefix.len()..].trim().parse().unwrap()
    }

    fn bulk_read(&mut self, endpoint: u8, buf: &mut [u8], timeout_ms: u32) -> i32 {
        let Some(line) = self.next_line("BULK") else { return -1 };
        let prefix = std::format!("T B {endpoint:02x} {} {timeout_ms} -> ", buf.len());
        if !self.expect_prefix(&line, &prefix) {
            return -1;
        }
        for (i, b) in buf.iter_mut().enumerate() {
            *b = (i as u8).wrapping_mul(7).wrapping_add(3);
        }
        let mut it = line[prefix.len()..].split(' ');
        let _status = it.next();
        it.next().unwrap().parse().unwrap()
    }

    fn string_descriptor(&mut self, which: UsbString, out: &mut [u8]) -> i32 {
        let Some(line) = self.next_line("STRING") else { return -1 };
        let idx = match which {
            UsbString::Manufacturer => 1,
            UsbString::Product => 2,
            UsbString::Serial => 3,
        };
        let prefix = std::format!("T S {idx} -> ");
        if !self.expect_prefix(&line, &prefix) {
            return -1;
        }
        let mut it = line[prefix.len()..].splitn(2, ' ');
        let n: i32 = it.next().unwrap().parse().unwrap();
        let s = it.next().unwrap_or("");
        let m = s.len().min(out.len());
        out[..m].copy_from_slice(&s.as_bytes()[..m]);
        n
    }

    fn reset_device(&mut self) -> i32 {
        if let Some(line) = self.next_line("RESET") {
            self.expect_prefix(&line, "T X reset");
        }
        0
    }
}

fn num(arg: &str) -> i64 {
    if let Some(h) = arg.strip_prefix("0x") {
        i64::from_str_radix(h, 16).unwrap()
    } else {
        arg.parse().unwrap()
    }
}

fn pair(arg: &str) -> (i64, Option<i64>) {
    match arg.split_once(':') {
        Some((a, b)) => (num(a), Some(num(b))),
        None => (num(arg), None),
    }
}

/// Runs the command script (the language of ref_harness.c) over the replay; the R lines are checked as they come.
fn run_script(name: &str, cmds: &str, log: &str) {
    let mut dev: Option<RtlSdr<Replay>> = None;
    let mut replay = Some(Replay::new(log));
    for cmd in cmds.split_whitespace() {
        let (c, arg) = cmd.split_once('=').unwrap_or((cmd, ""));
        if c == "open" {
            let r = RtlSdr::open(replay.take().unwrap());
            match r {
                Ok(d) => {
                    dev = Some(d);
                    dev.as_mut().unwrap().transport().check_r("open", 0);
                }
                Err((e, mut t)) => {
                    t.check_r("open", e as i64);
                    replay = Some(t);
                }
            }
            continue;
        }
        let Some(d) = dev.as_mut() else {
            replay.as_mut().unwrap().check_r(c, 0x7fff_ffff);
            continue;
        };
        let n = if arg.is_empty() { 0 } else { num(arg.split(':').next().unwrap()) };
        let r: Option<i64> = match c {
            "close" => {
                let mut t = dev.take().unwrap().close();
                t.check_r("close", 0);
                replay = Some(t);
                continue;
            }
            "cf" => Some(d.set_center_freq(n as u32) as i64),
            "sr" => Some(d.set_sample_rate(n as u32) as i64),
            "ppm" => Some(d.set_freq_correction(n as i32) as i64),
            "gm" => Some(d.set_tuner_gain_mode(n as i32) as i64),
            "g" => Some(d.set_tuner_gain(n as i32) as i64),
            "ig" => Some(d.set_tuner_if_gain(n as i32, pair(arg).1.unwrap_or(0) as i32) as i64),
            "bw" => Some(d.set_tuner_bandwidth(n as u32) as i64),
            "agc" => Some(d.set_agc_mode(n != 0) as i64),
            "ds" => Some(d.set_direct_sampling(n as i32) as i64),
            "off" => Some(d.set_offset_tuning(n != 0) as i64),
            "bias" => Some(d.set_bias_tee(n != 0) as i64),
            "biasgpio" => Some(d.set_bias_tee_gpio(n as u8, pair(arg).1.unwrap_or(0) != 0) as i64),
            "reset" => Some(d.reset_buffer() as i64),
            "test" => Some(d.set_testmode(n != 0) as i64),
            "read" => {
                let mut b = std::vec![0u8; n as usize];
                let r = d.read_sync(&mut b);
                let t = d.transport();
                t.check_r("read", if r < 0 { r as i64 } else { 0 });
                t.check_r("read_n", r.max(0) as i64);
                continue;
            }
            "xtal" => Some(d.set_xtal_freq(n as u32, pair(arg).1.unwrap_or(0) as u32) as i64),
            "eeprom_r" => {
                let len = pair(arg).1.unwrap_or(1) as usize;
                let mut b = std::vec![0u8; len];
                let r = d.read_eeprom(&mut b, n as u8);
                let t = d.transport();
                t.check_r("eeprom_r", r as i64);
                if r >= 0 {
                    let want = std::format!("R eeprom {}", hex(&b));
                    if t.lines.get(t.pos) != Some(&want) {
                        t.mismatches.push(std::format!("eeprom: wanted `{want}`, log has {:?}", t.lines.get(t.pos)));
                    }
                    t.pos += 1;
                }
                continue;
            }
            "eeprom_w" => {
                let h = arg.split_once(':').map(|x| x.1).unwrap_or("");
                let data = unhex(h);
                Some(d.write_eeprom(&data, n as u8) as i64)
            }
            "info" => {
                let mut g = [0i32; 40];
                let cnt = d.get_tuner_gains(Some(&mut g));
                let vals = [
                    ("tuner", d.get_tuner_type().code() as i64),
                    ("freq", d.get_center_freq() as i64),
                    ("rate", d.get_sample_rate() as i64),
                    ("corr", d.get_freq_correction() as i64),
                    ("dsm", d.get_direct_sampling() as i64),
                    ("offs", d.get_offset_tuning() as i64),
                    ("gain", d.get_tuner_gain() as i64),
                    ("ngains", cnt as i64),
                ];
                let gl = g[..cnt as usize].iter().fold(String::from("R gains"), |s, v| s + &std::format!(" {v}"));
                let t = d.transport();
                for (k, v) in vals {
                    t.check_r(k, v);
                }
                if t.lines.get(t.pos) != Some(&gl) {
                    t.mismatches.push(std::format!("gains: wanted `{gl}`, log has {:?}", t.lines.get(t.pos)));
                }
                t.pos += 1;
                continue;
            }
            other => panic!("{name}: unknown command {other}"),
        };
        if let Some(v) = r {
            d.transport().check_r(c, v);
        }
    }
    // the harness closes a device that is still open at the end (no R line)
    let replay = match dev {
        Some(d) => d.close(),
        None => replay.unwrap(),
    };
    let mut mm = replay.mismatches;
    if replay.pos != replay.lines.len() {
        mm.push(std::format!("only {} of {} logged lines were consumed", replay.pos, replay.lines.len()));
    }
    assert!(mm.is_empty(), "{name}: {} mismatches, first: {:?}", mm.len(), &mm[..mm.len().min(3)]);
}

fn golden_dir() -> std::path::PathBuf {
    std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/golden")
}

#[test]
fn differential_against_original_librtlsdr() {
    let dir = golden_dir();
    let scen = std::fs::read_to_string(dir.join("scenarios.txt")).unwrap();
    let mut n = 0;
    let mut transfers = 0;
    for line in scen.lines().filter(|l| !l.starts_with('#') && !l.trim().is_empty()) {
        let mut p = line.splitn(3, '|');
        let name = p.next().unwrap();
        let _model = p.next().unwrap();
        let cmds = p.next().unwrap();
        let log = std::fs::read_to_string(dir.join(std::format!("{name}.log"))).unwrap();
        transfers += log.lines().filter(|l| l.starts_with("T ")).count();
        run_script(name, cmds, &log);
        n += 1;
    }
    assert!(n >= 80, "scenarios found: {n}");
    std::println!("{n} scenarios, {transfers} transfers compared with the original: 0 mismatches");
}

#[test]
fn gain_tables_and_tuner_codes() {
    let mut d = RtlSdr::open(FakeRtl::new(FakeChip::R820T)).ok().unwrap();
    assert_eq!(d.get_tuner_type(), Tuner::R820T);
    assert_eq!(d.get_tuner_type().code(), 5);
    assert_eq!(d.get_tuner_gains(None), 29);
    let mut g = [0i32; 29];
    assert_eq!(d.get_tuner_gains(Some(&mut g)), 29);
    assert_eq!((g[0], g[28]), (0, 496));
    assert_eq!(d.set_sample_rate(2_048_000), 0);
    assert_eq!(d.get_sample_rate(), 2_048_000);
    assert_eq!(d.set_sample_rate(225_000), -22);
    assert_eq!(d.set_sample_rate(500_000), -22);
    let e = RtlSdr::open(FakeRtl::new(FakeChip::E4000)).ok().unwrap();
    assert_eq!(e.get_tuner_type(), Tuner::E4000);
    assert_eq!(e.get_tuner_gains(None), 14);
    let n = RtlSdr::open(FakeRtl::new(FakeChip::None)).ok().unwrap();
    assert_eq!(n.get_tuner_type(), Tuner::Unknown);
    assert_eq!(n.get_direct_sampling(), 1);
    assert_eq!(n.get_tuner_gains(None), 1);
}

#[test]
fn tunes_r820t_pll_to_known_registers() {
    // 100 MHz + 3.57 MHz IF = 103.57 MHz LO; divider 32 (VCO 3314.24 MHz), Ni/Si and SDM follow from the 28.8 MHz crystal
    let mut d = RtlSdr::open(FakeRtl::new(FakeChip::R820T)).ok().unwrap();
    assert_eq!(d.set_sample_rate(2_048_000), 0);
    assert_eq!(d.set_center_freq(100_000_000), 0);
    assert_eq!(d.get_center_freq(), 100_000_000);
    let f = d.transport();
    // register 0x14 = ni + (si << 6) with nint = vco / (2 * 28.8 MHz) = 57
    assert_eq!(f.chip_reg(0x34, 0x14), 11);
    // the VCO current is set to the maximum (RTL-SDR Blog change)
    assert_eq!(f.chip_reg(0x34, 0x12) & 0xf7, 0x06);
}

#[test]
fn bias_tee_gpio_and_forced_bias_tee() {
    let mut d = RtlSdr::open(FakeRtl::new(FakeChip::R820T)).ok().unwrap();
    assert_eq!(d.transport().sys_reg(0x3001) & 1, 0);
    d.set_bias_tee(true);
    assert_eq!(d.transport().sys_reg(0x3001) & 1, 1);
    d.set_bias_tee(false);
    assert_eq!(d.transport().sys_reg(0x3001) & 1, 0);
    // an EEPROM with the IR endpoint bit cleared forces the bias tee on and refuses to turn it off
    let mut f = FakeRtl::new(FakeChip::R820T);
    f.eeprom_forces_bias_tee();
    let mut d = RtlSdr::open(f).ok().unwrap();
    assert_eq!(d.transport().sys_reg(0x3001) & 1, 1);
    d.set_bias_tee(false);
    assert_eq!(d.transport().sys_reg(0x3001) & 1, 1);
    // GPIO 5 (V4 upconverter switch) is not subject to the force
    d.set_bias_tee_gpio(5, false);
    assert_eq!(d.transport().sys_reg(0x3001) & 0x20, 0);
}

#[test]
fn unsupported_fitipower_tuner_is_recognised_not_driven() {
    match RtlSdr::open(FakeRtl::new(FakeChip::Fc0013)) {
        Err((e, _)) => assert_eq!(e, -95),
        Ok(_) => panic!("FC0013 must not open"),
    }
}

#[test]
fn dongle_model_strings() {
    let mut f = FakeRtl::new(FakeChip::R828D);
    f.vendor = "RTLSDRBlog";
    f.product = "Blog V4";
    let d = RtlSdr::open(f).ok().unwrap();
    assert!(d.check_dongle_model("RTLSDRBlog", "Blog V4"));
    assert!(!d.check_dongle_model("RTLSDRBlog", "Blog V3"));
    assert!(!d.check_dongle_model("RTLSDRBlog", "Blog V"));
    assert_eq!(d.usb_strings().1, b"Blog V4");
}

#[test]
fn eeprom_roundtrip_and_bounds() {
    let mut d = RtlSdr::open(FakeRtl::new(FakeChip::R820T)).ok().unwrap();
    assert_eq!(d.write_eeprom(&[0xaa, 0xbb, 0xcc], 10), 0);
    let mut b = [0u8; 3];
    assert!(d.read_eeprom(&mut b, 10) >= 0);
    assert_eq!(b, [0xaa, 0xbb, 0xcc]);
    assert_eq!(d.write_eeprom(&[0; 3], 254), -2);
    assert_eq!(d.read_eeprom(&mut [0u8; 3], 254), -2);
}

#[test]
fn failing_transfers_do_not_panic_and_report_errors() {
    // every transfer fails: open still returns (like the C), later calls report failure
    struct Dead;
    impl UsbTransfer for Dead {
        fn control_in(&mut self, _: u8, _: u8, _: u16, _: u16, _: &mut [u8], _: u32) -> i32 {
            -4
        }
        fn control_out(&mut self, _: u8, _: u8, _: u16, _: u16, _: &[u8], _: u32) -> i32 {
            -4
        }
        fn bulk_read(&mut self, _: u8, _: &mut [u8], _: u32) -> i32 {
            -4
        }
    }
    let mut d = RtlSdr::open(Dead).ok().unwrap();
    assert_eq!(d.get_tuner_type(), Tuner::Unknown);
    assert_eq!(d.read_sync(&mut [0u8; 16]), -4);
    assert_ne!(d.set_sample_rate(2_048_000), 0);
    let _ = d.set_center_freq(100_000_000);
    assert_eq!(d.get_center_freq(), 0);
    d.close();
}

#[test]
fn short_and_garbled_answers_from_the_fake() {
    for chip in [FakeChip::R820T, FakeChip::R828D, FakeChip::E4000, FakeChip::None] {
        for every in 1..30 {
            let mut f = FakeRtl::new(chip);
            f.corrupt_every = every;
            f.seed(every * 77);
            if let Ok(mut d) = RtlSdr::open(f) {
                d.set_sample_rate(2_048_000);
                for fr in [7_000_000u32, 100_000_000, 433_000_000, 1_090_000_000, 0, u32::MAX] {
                    d.set_center_freq(fr);
                }
                d.set_tuner_gain_mode(1);
                d.set_tuner_gain(300);
                d.set_tuner_bandwidth(1_000_000);
                d.set_offset_tuning(true);
                d.set_direct_sampling(2);
                d.close();
            }
        }
    }
}

#[test]
fn seeded_fuzz_of_the_transfer_layer() {
    // xorshift seeded mutation: random buffers plus mutated copies of the golden answers
    let mut s = 0x2545_f491u32;
    let mut rnd = || {
        s ^= s << 13;
        s ^= s >> 17;
        s ^= s << 5;
        s
    };
    let mut total = 0u32;
    for case in 0..4000 {
        let len = 1 + (rnd() % 600) as usize;
        let mut data: Vec<u8> = (0..len).map(|_| rnd() as u8).collect();
        data[0] = case as u8;
        total = total.wrapping_add(fuzz::run(&data));
        // flip a few bytes of a previous input
        for _ in 0..3 {
            let i = rnd() as usize % data.len();
            data[i] ^= 1 << (rnd() % 8);
            total = total.wrapping_add(fuzz::run(&data));
        }
    }
    std::println!("fuzz checksum {total}");
    assert_eq!(fuzz::run(&[]), 0);
}
